  const unsigned char *data = decode(ts_compact_zstd, sizeof(ts_compact_zstd), 4084896, 4009244);
  language.small_parse_table = (const uint16_t *)data;
  language.small_parse_table_map = (const uint32_t *)(data + 4009244);
